import 'package:flutter_bloc/flutter_bloc.dart';import 'package:firebase_auth/firebase_auth.dart';import 'package:sehatak/core/services/child_service.dart';import 'package:sehatak/core/models/child/child_models.dart';import 'child_event.dart';import 'child_state.dart';class ChildBloc extends Bloc<ChildEvent,ChildState>{final ChildService service;ChildBloc({ChildService?service}):service=service??ChildService(),super(const ChildState()){on<ChildStarted>(_load);on<ChildRefreshed>(_load);on<ChildFilterBySpecialty>(_filter);on<ChildSearch>(_search);on<ChildUpdateTracker>(_update);}Future<void>_load(ChildEvent e,Emitter<ChildState>emit)async{emit(state.copyWith(isLoading:true,errorMessage:null));try{final u=FirebaseAuth.instance.currentUser?.uid;final r=await Future.wait([service.getTopDoctors(limit:20),service.streamClinics(limit:20).first,service.streamTips(limit:20).first,service.streamHospitals(limit:10)]);final t=u==null?null:await service.getTracker(u);emit(state.copyWith(isLoading:false,doctors:r[0]as List<ChildDoctor>,clinics:r[1]as List<ChildClinic>,tips:r[2]as List<ChildTip>,hospitals:r[3]as List<ChildHospital>,tracker:t));}catch(x){emit(state.copyWith(isLoading:false,errorMessage:x.toString()));}}Future<void>_filter(ChildFilterBySpecialty e,Emitter<ChildState>emit)async{emit(state.copyWith(isLoading:true,selectedSpecialty:e.specialty));try{emit(state.copyWith(isLoading:false,doctors:await service.streamDoctors(specialty:e.specialty).first));}catch(x){emit(state.copyWith(isLoading:false,errorMessage:x.toString()));}}void _search(ChildSearch e,Emitter<ChildState>emit){final q=e.query.toLowerCase();emit(state.copyWith(doctors:state.doctors.where((d)=>d.name.toLowerCase().contains(q)||d.specialty.toLowerCase().contains(q)).toList()));}Future<void>_update(ChildUpdateTracker e,Emitter<ChildState>emit)async{final uid=FirebaseAuth.instance.currentUser?.uid;if(uid==null)return;try{await service.updateGrowth(uid,height:(e.data['height']as num?)?.toDouble(),weight:(e.data['weight']as num?)?.toDouble());if(e.data['birthDate']!=null)await service.updateGrowth(uid,height:(e.data['height']as num?)?.toDouble(),weight:(e.data['weight']as num?)?.toDouble());emit(state.copyWith(tracker:await service.getTracker(uid)));}catch(x){emit(state.copyWith(errorMessage:x.toString()));}}}
